sys_ui_action.client_script_v2:
function onClick(g_form) {
    if (g_form.getValue('comments') == '') {
        g_form.setMandatory('comments', true);
        //g_form.addErrorMessage("Please update the comments before closing the exception case record");
		g_modal.alert("Please add your comments before closing this case");
        return false; //Abort submission
    } else {
        g_modal.confirm("Please confirm if you want to close the exception case?", function(closedconfirmed) {
            if (closedconfirmed == true) {
                g_form.submit('collateral_close_case');
            } else {
                return false;
            }
        });
    }
}

sys_ui_action.script:
function checkCommentsBeforeClose() {
    if (g_form.getValue('comments') == '') {
        g_form.setMandatory('comments', true);
        g_form.addErrorMessage('Please add your comments before closing this case');
        return false; //Abort submission
    } else {
        g_form.clearMessages();
		var closeconfirmed = confirm("Please confirm if you want to close the exception case?");
        if (closeconfirmed == true) {
            gsftSubmit(null, g_form.getFormElement(), 'collateral_close_case');
        }
		else{
			return false;
		}
    }
}

if (typeof window == 'undefined') {
    serverClose();
}

function serverClose() {
    current.state = 3;
    //current.work_notes = "Case closed. Comments: " + current.comments;
    gs.addInfoMessage('Exception Case ' + current.number + ' has been closed.');
    current.update();
    action.setRedirectURL(current);
}
